(1356, 334, 2, 'commented', 'comment', NULL, '<p>Definir roles :</p><ol><li>Propietario</li><li>Editor</li><li>Comentarista</li><li>Lector/visualizador</li></ol>', NULL, 'Comentario agregado', '2025-09-03 18:31:12'),
(1357, 341, 40, 'created', 'subtask', NULL, 'Presentación de la propuesta', NULL, 'Subtarea creada: Presentación de la propuesta', '2025-09-03 18:31:29'),
(1358, 334, 2, 'commented', 'comment', NULL, '<p>Diagrama de Usuarios y arquitectura: </p>', NULL, 'Comentario agregado', '2025-09-03 18:31:40'),
(1359, 334, 2, 'created', 'subtask', NULL, 'Arquitectura de usuarios', NULL, 'Subtarea creada: Arquitectura de usuarios', '2025-09-03 18:32:25'),
(1360, 334, 2, 'assigned', 'subtask_assignment', 'múltiples usuarios', 'Abdiel Carrasco', NULL, 'Subtarea \"Arquitectura de usuarios\" asignada a 1 usuario(s): Abdiel Carrasco', '2025-09-03 18:32:54'),
(1361, 334, 2, 'commented', 'subtask_comment', NULL, '<ol><li><strong>Propietario (Owner)</strong></li></ol><ul><li class=\"ql-indent-1\">Control total del archivo/carpeta.</li><li class=\"ql-indent-1\">Puede ver, comentar, editar, eliminar y transferir la propiedad.</li><li class=\"ql-indent-1\">Decide quién tiene acceso y con qué nivel de permisos.</li></ul><ol><li><strong>Editor (Editor)</strong></li></ol><ul><li class=\"ql-indent-1\">Puede ver y <strong>modificar</strong> el archivo.</li><li class=\"ql-indent-1\">Puede añadir, cambiar o borrar contenido.</li><li class=\"ql-indent-1\">En carpetas: puede agregar/eliminar archivos.</li><li class=\"ql-indent-1\">No puede cambiar la propiedad ni quitar al propietario.</li></ul><ol><li><strong>Comentarista (Commenter)</strong></li></ol><ul><li class=\"ql-indent-1\">Puede ver el archivo.</li><li class=\"ql-indent-1\">Puede <strong>agregar comentarios y sugerencias</strong>, pero no modificar directamente el contenido.</li><li class=\"ql-indent-1\">Útil para revisiones o feedback.</li></ul><ol><li><strong>Lector/Visualizador (Viewer)</strong></li></ol><ul><li class=\"ql-indent-1\">Solo puede <strong>ver</strong> el archivo o carpeta.</li><li class=\"ql-indent-1\">No puede comentar ni editar.</li><li class=\"ql-indent-1\">Es el nivel de acceso más restrictivo sin quitar visibilidad.</li></ul><p><br></p>', NULL, 'Comentario agregado en subtarea: Arquitectura de usuarios', '2025-09-03 18:34:39'),
